      // string property is advertised; the response bridge unwraps it back
      // into the raw input and delivers a custom_tool_call item.
      flat.push({
        type: "function",
        function: {
          name,
          description: tool.description || "",
          parameters:
            tool.parameters ||
            (tool.type === "custom"
              ? {
                  type: "object",
                  properties: {
                    content: {
                      type: "string",
                      description:
                        "The " + name + " content following the specified format",
