{"code":"const r = await tools.bash({command: `bun -e '
const srv = Bun.serve({
  port: 0,
  async fetch(req) {
    const url = new URL(req.url);
    if (url.pathname === \"/echo\") {
      // echo headers + raw body info
      const ce = req.headers.get(\"content-encoding\");
      const buf = Buffer.from(await req.arrayBuffer());
      let jsonErr = null, jsonVal = null;
      try { jsonVal = await new Response(buf).json(); } catch(e){ jsonErr = e.message; }
      // try Bun decompress if zstd?
      let decomp = null;
      if (ce && ce.includes(\"zstd\")) {
        try { decomp = Buffer.from(Bun.zstdDecompressSync(buf)).toString(\"utf8\").slice(0,200); } catch(e){ decomp = \"decomp-err: \"+e.message; }
      }
      return Response.json({ce, len: buf.length, head: Array.from(buf.slice(0,20)), jsonErr, decomp});
    }
    if (url.pathname === \"/zstd-json\") {
      const obj = {hello: \"world\", n: 123};
      const comp = Buffer.from(Bun.zstdCompressSync(Buffer.from(JSON.stringify(obj))));
      return new Response(comp, {headers: {\"Content-Type\":\"application/json\", \"Content-Encoding\":\"zstd\"}});
    }
    if (url.pathname === \"/headers\") {
      const ae = req.headers.get(\"accept-encoding\");
      return Response.json({ae});
    }
    return Response.json({ok:true});
  }
});
const base = \"http://127.0.0.1:\"+srv.port;
// 1. what Accept-Encoding does Bun fetch send by default?
let h = await (await fetch(base+\"/headers\")).json();
console.log(\"default fetch Accept-Encoding:\", h.ae);
h = await (await fetch(base+\"/headers\", {headers: {Accept: \"text/event-stream, application/json\"}})).json();
console.log(\"with Accept header, Accept-Encoding:\", h.ae);
// 2. does fetch auto-decompress zstd?
let r = await fetch(base+\"/zstd-json\");
console.log(\"zstd-json content-encoding seen by client:\", r.headers.get(\"content-encoding\"));
console.log(\"zstd-json content-type:\", r.headers.get(\"content-type\"));
try {
  const j = await r.json();
  console.log(\"zstd-json .json() OK:\", JSON.stringify(j));
} catch(e){ console.log(\"zstd-json .json() ERR:\", e.message); }
// text path
let r2 = await fetch(base+\"/zstd-json\");
try { const t = await r2.text(); console.log(\"zstd-json .text() len:\", t.length, \"head:\", t.slice(0,80)); } catch(e){ console.log(\"text err\", e.message); }
// 3. inbound: send zstd body with content-encoding
