  console.log("node deflate", c2.length);
  try { const d3 = Buffer.from(Bun.inflateSync(c2)); console.log("Bun inflate node-comp ok", d3.length===buf.length); } catch(e){ console.log("Bun inflate node-comp fail", e.message); }
} catch(e){ console.log("deflate err", e.message); }
// br
try {
  const c = zlib.brotliCompressSync(buf);
  console.log("node br comp", c.length);
  const d = zlib.brotliDecompressSync(c);
  console.log("node br roundtrip", d.length===buf.length);
} catch(e){ console.log("br err", e.message); }
